CREATE VIEW dbo.IV_Q$ACOMP_VEND_MAQUINAS ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario,  DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao,  SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , FORMULARIO_NUMERO, CREEPER_CR, TROCA_DE_EIXO_3_METR, TROCAPNEUS, PESOS_CONFIGURACAO_F, TIPO_EQUIPAMENTO, INSTALACAO_CABINE, TROCA_DE_ASSENTO, INSTALACAO_VCRINSTAL, COTACAO, MARCA, FDD, MODELO_EQUIPAMENTO, QTDE_PESO_TRASEIRO__, KG_PESO_TRASEIRO__1_, POSICAO_PESO_TRASEIR, QTDE_PESO_TRAS2, KG_PESO_TRASEIRO__2_, POSICAO_PESO_TRASEI2, QTDE_PESO_DIANTEIRO, KG_PESO_DIANTEIRO, LASTRO_DIANTEIRO__, LASTRO_TRASEIRO, RODADO_TRASEIRO, RODADO_DIANTEIRO, QTDE_VCR_100, QTDE_VCR_300, MEDIDA_BITOLA, POSICAO_BITOLA, AMS, RECEPTOR, RADIO, ATIVACAO, MONITOR, VOLANTE, CONECTIVIDADCONECTIV, CONFIGURACOES_AMS, CHASSI, INFORMACAO_PREPARACA, PREVISAO_ENTREGA_PRE, DATA_ENTREGA, TRANSPORTE_ENTREGA, TRANSPORTADORA, VALOR_FRETE, PRODUTO_NOVO_OU_USAD, FORMULARIO_NUMERO1, DESCONTO_INCONDICION, TRANSPORTE_ENTREGA1, MEU_PRIMEIRO_JD)     AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO,  QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS,  QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO,  QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.FORMULARIO_NUMERO, TABF.CREEPER_CR, TABF.TROCA_DE_EIXO_3_METR, TABF.TROCAPNEUS, TABF.PESOS_CONFIGURACAO_F, TABF.TIPO_EQUIPAMENTO, TABF.INSTALACAO_CABINE, TABF.TROCA_DE_ASSENTO, TABF.INSTALACAO_VCRINSTAL, TABF.COTACAO, TABF.MARCA, TABF.FDD, TABF.MODELO_EQUIPAMENTO, TABF.QTDE_PESO_TRASEIRO__, TABF.KG_PESO_TRASEIRO__1_, TABF.POSICAO_PESO_TRASEIR, TABF.QTDE_PESO_TRAS2, TABF.KG_PESO_TRASEIRO__2_, TABF.POSICAO_PESO_TRASEI2, TABF.QTDE_PESO_DIANTEIRO, TABF.KG_PESO_DIANTEIRO, TABF.LASTRO_DIANTEIRO__, TABF.LASTRO_TRASEIRO, TABF.RODADO_TRASEIRO, TABF.RODADO_DIANTEIRO, TABF.QTDE_VCR_100, TABF.QTDE_VCR_300, TABF.MEDIDA_BITOLA, TABF.POSICAO_BITOLA, TABF.AMS, TABF.RECEPTOR, TABF.RADIO, TABF.ATIVACAO, TABF.MONITOR, TABF.VOLANTE, TABF.CONECTIVIDADCONECTIV, TABF.CONFIGURACOES_AMS, TABF.CHASSI, TABF.INFORMACAO_PREPARACA, TABF.PREVISAO_ENTREGA_PRE, TABF.DATA_ENTREGA, TABF.TRANSPORTE_ENTREGA, TABF.TRANSPORTADORA, TABF.VALOR_FRETE, TABF.PRODUTO_NOVO_OU_USAD, TABF.FORMULARIO_NUMERO1, TABF.DESCONTO_INCONDICION, TABF.TRANSPORTE_ENTREGA1, TABF.MEU_PRIMEIRO_JD    FROM IV_Q_ACOMP_VEND_MAQUINAS TABF  	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO  	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO  	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA 